        end else if(field_combo.dbg_reg.data.load_next) begin
            field_storage.dbg_reg.data.value <= field_combo.dbg_reg.data.next;
        end
    end
    assign hwif_out.dbg_reg.data.value = field_storage.dbg_reg.data.value;
    // Field: expanded_regfile.err_reg.control
    always_comb begin
        automatic logic [3:0] next_c;
        automatic logic load_next_c;
        next_c = field_storage.err_reg.control.value;
        load_next_c = '0;
        if(decoded_reg_strb.err_reg && decoded_req_is_wr) begin // SW write
            next_c = (field_storage.err_reg.control.value & ~decoded_wr_biten[3:0]) | (decoded_wr_data[3:0] & decoded_wr_biten[3:0]);
            load_next_c = '1;
        end
        field_combo.err_reg.control.next = next_c;
        field_combo.err_reg.control.load_next = load_next_c;
    end
    always_ff @(posedge clk) begin
        if(rst) begin
            field_storage.err_reg.control.value <= 4'h0;
        end else if(field_combo.err_reg.control.load_next) begin
            field_storage.err_reg.control.value <= field_combo.err_reg.control.next;
        end
    end
    assign hwif_out.err_reg.control.value = field_storage.err_reg.control.value;
    // Field: expanded_regfile.err_reg.data
    always_comb begin
        automatic logic [7:0] next_c;
        automatic logic load_next_c;
        next_c = field_storage.err_reg.data.value;
        load_next_c = '0;
        if(decoded_reg_strb.err_reg && decoded_req_is_wr) begin // SW write
            next_c = (field_storage.err_reg.data.value & ~decoded_wr_biten[15:8]) | (decoded_wr_data[15:8] & decoded_wr_biten[15:8]);
            load_next_c = '1;
        end else if(hwif_in.err_reg.data.we) begin // HW Write - we
            next_c = hwif_in.err_reg.data.next;
            load_next_c = '1;
        end
        field_combo.err_reg.data.next = next_c;
        field_combo.err_reg.data.load_next = load_next_c;
    end
    always_ff @(posedge clk) begin
        if(rst) begin
            field_storage.err_reg.data.value <= 8'h0;
        end else if(field_combo.err_reg.data.load_next) begin
            field_storage.err_reg.data.value <= field_combo.err_reg.data.next;
        end
    end
    assign hwif_out.err_reg.data.value = field_storage.err_reg.data.value;
    // Field: expanded_regfile.fifostatus.data
    always_comb begin
        automatic logic [12:0] next_c;
        automatic logic load_next_c;
        next_c = field_storage.fifostatus.data.value;
        load_next_c = '0;
        if(decoded_reg_strb.fifostatus && decoded_req_is_wr) begin // SW write
            next_c = (field_storage.fifostatus.data.value & ~decoded_wr_biten[15:3]) | (decoded_wr_data[15:3] & decoded_wr_biten[15:3]);
            load_next_c = '1;
        end
        field_combo.fifostatus.data.next = next_c;
        field_combo.fifostatus.data.load_next = load_next_c;
    end
    always_ff @(posedge clk) begin
        if(rst) begin
            field_storage.fifostatus.data.value <= 13'h0;
        end else if(field_combo.fifostatus.data.load_next) begin
            field_storage.fifostatus.data.value <= field_combo.fifostatus.data.next;
        end
    end
    assign hwif_out.fifostatus.data.value = field_storage.fifostatus.data.value;
    // Field: expanded_regfile.fifostatus.reserved
    always_comb begin
        automatic logic [15:0] next_c;
        automatic logic load_next_c;
        next_c = field_storage.fifostatus.reserved.value;
        load_next_c = '0;
        if(decoded_reg_strb.fifostatus && decoded_req_is_wr) begin // SW write
            next_c = (field_storage.fifostatus.reserved.value & ~decoded_wr_biten[31:16]) | (decoded_wr_data[31:16] & decoded_wr_biten[31:16]);
            load_next_c = '1;
        end
        field_combo.fifostatus.reserved.next = next_c;
        field_combo.fifostatus.reserved.load_next = load_next_c;
    end
    always_ff @(posedge clk) begin
        if(rst) begin
            field_storage.fifostatus.reserved.value <= 16'h0;
        end else if(field_combo.fifostatus.reserved.load_next) begin
            field_storage.fifostatus.reserved.value <= field_combo.fifostatus.reserved.next;
        end
    end
    assign hwif_out.fifostatus.reserved.value = field_storage.fifostatus.reserved.value;

    //--------------------------------------------------------------------------
    // Write response
    //--------------------------------------------------------------------------
    assign cpuif_wr_ack = decoded_req & decoded_req_is_wr;
    // Writes are always granted with no error response
    assign cpuif_wr_err = '0;

    //--------------------------------------------------------------------------
    // Readback
    //--------------------------------------------------------------------------

    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;

    // Assign readback values to a flattened array
    logic [31:0] readback_array[16];
    assign readback_array[0][3:0] = (decoded_reg_strb.init_control_status && !decoded_req_is_wr) ? field_storage.init_control_status.control.value : '0;
    assign readback_array[0][7:4] = (decoded_reg_strb.init_control_status && !decoded_req_is_wr) ? hwif_in.init_control_status.status.next : '0;
    assign readback_array[0][15:8] = (decoded_reg_strb.init_control_status && !decoded_req_is_wr) ? field_storage.init_control_status.data.value : '0;
