    assign readback_array[1][31:16] = '0;
    assign readback_array[2][3:0] = (decoded_reg_strb.interrupt_control && !decoded_req_is_wr) ? field_storage.interrupt_control.control.value : '0;
    assign readback_array[2][7:4] = (decoded_reg_strb.interrupt_control && !decoded_req_is_wr) ? hwif_in.interrupt_control.status.next : '0;
    assign readback_array[2][15:8] = (decoded_reg_strb.interrupt_control && !decoded_req_is_wr) ? field_storage.interrupt_control.data.value : '0;
    assign readback_array[2][31:16] = '0;
    assign readback_array[3][3:0] = (decoded_reg_strb.power_control_status && !decoded_req_is_wr) ? field_storage.power_control_status.control.value : '0;
    assign readback_array[3][4:4] = (decoded_reg_strb.power_control_status && !decoded_req_is_wr) ? field_storage.power_control_status.status.value : '0;
    assign readback_array[3][8:5] = (decoded_reg_strb.power_control_status && !decoded_req_is_wr) ? field_storage.power_control_status.counter.value : '0;
    assign readback_array[3][15:9] = (decoded_reg_strb.power_control_status && !decoded_req_is_wr) ? field_storage.power_control_status.data.value : '0;
    assign readback_array[3][31:16] = '0;
    assign readback_array[4][3:0] = (decoded_reg_strb.reset_control_status && !decoded_req_is_wr) ? field_storage.reset_control_status.control.value : '0;
    assign readback_array[4][7:4] = (decoded_reg_strb.reset_control_status && !decoded_req_is_wr) ? hwif_in.reset_control_status.status.next : '0;
    assign readback_array[4][15:8] = (decoded_reg_strb.reset_control_status && !decoded_req_is_wr) ? field_storage.reset_control_status.data.value : '0;
    assign readback_array[4][31:16] = '0;
    assign readback_array[5][3:0] = (decoded_reg_strb.transmit_control_status && !decoded_req_is_wr) ? field_storage.transmit_control_status.control.value : '0;
    assign readback_array[5][7:4] = (decoded_reg_strb.transmit_control_status && !decoded_req_is_wr) ? hwif_in.transmit_control_status.status.next : '0;
    assign readback_array[5][15:8] = (decoded_reg_strb.transmit_control_status && !decoded_req_is_wr) ? field_storage.transmit_control_status.data.value : '0;
    assign readback_array[5][31:16] = '0;
    assign readback_array[6][3:0] = (decoded_reg_strb.csr_reg && !decoded_req_is_wr) ? field_storage.csr_reg.control.value : '0;
    assign readback_array[6][7:4] = (decoded_reg_strb.csr_reg && !decoded_req_is_wr) ? hwif_in.csr_reg.status.next : '0;
    assign readback_array[6][15:8] = (decoded_reg_strb.csr_reg && !decoded_req_is_wr) ? field_storage.csr_reg.data.value : '0;
    assign readback_array[6][31:16] = '0;
    assign readback_array[7][3:0] = (decoded_reg_strb.conf_reg && !decoded_req_is_wr) ? field_storage.conf_reg.control.value : '0;
    assign readback_array[7][7:4] = (decoded_reg_strb.conf_reg && !decoded_req_is_wr) ? hwif_in.conf_reg.status.next : '0;
    assign readback_array[7][15:8] = (decoded_reg_strb.conf_reg && !decoded_req_is_wr) ? field_storage.conf_reg.data.value : '0;
    assign readback_array[7][31:16] = '0;
    assign readback_array[8][3:0] = (decoded_reg_strb.sys_stat_reg && !decoded_req_is_wr) ? field_storage.sys_stat_reg.control.value : '0;
    assign readback_array[8][7:4] = (decoded_reg_strb.sys_stat_reg && !decoded_req_is_wr) ? hwif_in.sys_stat_reg.status.next : '0;
    assign readback_array[8][15:8] = (decoded_reg_strb.sys_stat_reg && !decoded_req_is_wr) ? field_storage.sys_stat_reg.data.value : '0;
    assign readback_array[8][31:16] = '0;
    assign readback_array[9][3:0] = (decoded_reg_strb.int_reg && !decoded_req_is_wr) ? field_storage.int_reg.control.value : '0;
    assign readback_array[9][7:4] = (decoded_reg_strb.int_reg && !decoded_req_is_wr) ? hwif_in.int_reg.status.next : '0;
    assign readback_array[9][15:8] = (decoded_reg_strb.int_reg && !decoded_req_is_wr) ? field_storage.int_reg.data.value : '0;
    assign readback_array[9][31:16] = '0;
    assign readback_array[10][3:0] = (decoded_reg_strb.cntrl_reg && !decoded_req_is_wr) ? field_storage.cntrl_reg.control.value : '0;
    assign readback_array[10][7:4] = (decoded_reg_strb.cntrl_reg && !decoded_req_is_wr) ? hwif_in.cntrl_reg.status.next : '0;
    assign readback_array[10][15:8] = (decoded_reg_strb.cntrl_reg && !decoded_req_is_wr) ? field_storage.cntrl_reg.data.value : '0;
