    assign readback_array[11][3:0] = (decoded_reg_strb.perf_reg && !decoded_req_is_wr) ? field_storage.perf_reg.control.value : '0;
    assign readback_array[11][7:4] = (decoded_reg_strb.perf_reg && !decoded_req_is_wr) ? hwif_in.perf_reg.status.next : '0;
    assign readback_array[11][15:8] = (decoded_reg_strb.perf_reg && !decoded_req_is_wr) ? field_storage.perf_reg.data.value : '0;
    assign readback_array[11][31:16] = '0;
    assign readback_array[12][3:0] = (decoded_reg_strb.pm_reg && !decoded_req_is_wr) ? field_storage.pm_reg.control.value : '0;
    assign readback_array[12][7:4] = (decoded_reg_strb.pm_reg && !decoded_req_is_wr) ? hwif_in.pm_reg.status.next : '0;
