    assign readback_array[14][3:0] = (decoded_reg_strb.err_reg && !decoded_req_is_wr) ? field_storage.err_reg.control.value : '0;
    assign readback_array[14][7:4] = (decoded_reg_strb.err_reg && !decoded_req_is_wr) ? hwif_in.err_reg.status.next : '0;
    assign readback_array[14][15:8] = (decoded_reg_strb.err_reg && !decoded_req_is_wr) ? field_storage.err_reg.data.value : '0;
    assign readback_array[14][31:16] = '0;
    assign readback_array[15][0:0] = (decoded_reg_strb.fifostatus && !decoded_req_is_wr) ? hwif_in.fifostatus.empty.next : '0;
    assign readback_array[15][1:1] = (decoded_reg_strb.fifostatus && !decoded_req_is_wr) ? hwif_in.fifostatus.full.next : '0;
    assign readback_array[15][2:2] = (decoded_reg_strb.fifostatus && !decoded_req_is_wr) ? hwif_in.fifostatus.valid_data.next : '0;
    assign readback_array[15][15:3] = (decoded_reg_strb.fifostatus && !decoded_req_is_wr) ? field_storage.fifostatus.data.value : '0;
    assign readback_array[15][31:16] = (decoded_reg_strb.fifostatus && !decoded_req_is_wr) ? field_storage.fifostatus.reserved.value : '0;

    // Reduce the array
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
        readback_data_var = '0;
        for(int i=0; i<16; i++) readback_data_var |= readback_array[i];
        readback_data = readback_data_var;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
